@Finset.sum_pow_eq_sum_piAntidiag : ∀ {α : Type u_1} {R : Type u_2} [inst : DecidableEq α] [inst_1 : CommSemiring R]
  (s : Finset α) (f : α → R) (n : ℕ),
  (∑ i ∈ s, f i) ^ n = ∑ k ∈ s.piAntidiag n, ↑(Nat.multinomial s k) * ∏ i ∈ s, f i ^ k i
@Finset.sum_pow_eq_sum_piAntidiag_of_commute : ∀ {α : Type u_1} {R : Type u_2} [inst : DecidableEq α]
  [inst_1 : Semiring R] (s : Finset α) (f : α → R) (hc : (↑s).Pairwise (Function.onFun Commute f)) (n : ℕ),
  (∑ i ∈ s, f i) ^ n = ∑ k ∈ s.piAntidiag n, ↑(Nat.multinomial s k) * s.noncommProd (fun i => f i ^ k i) ⋯
@Finset.prod_univ_sum : ∀ {ι : Type u_1} {R : Type u_2} [inst : CommSemiring R] [inst_1 : DecidableEq ι]
  {κ : ι → Type u_3} [inst_2 : Fintype ι] (t : (i : ι) → Finset (κ i)) (f : (i : ι) → κ i → R),
  ∏ i, ∑ j ∈ t i, f i j = ∑ x ∈ Fintype.piFinset t, ∏ i, f i (x i)
@Fintype.prod_sum : ∀ {ι : Type u_1} {R : Type u_2} [inst : Fintype ι] [inst_1 : CommSemiring R]
  [inst_2 : DecidableEq ι] {κ : ι → Type u_3} [inst_3 : (i : ι) → Fintype (κ i)] (f : (i : ι) → κ i → R),
  ∏ i, ∑ j, f i j = ∑ x, ∏ i, f i (x i)
@Finset.mem_piAntidiag : ∀ {ι : Type u_1} {μ : Type u_2} [inst : DecidableEq ι] [inst_1 : AddCommMonoid μ]
  [inst_2 : Finset.HasAntidiagonal μ] [inst_3 : DecidableEq μ] {s : Finset ι} {n : μ} {f : ι → μ},
  f ∈ s.piAntidiag n ↔ s.sum f = n ∧ ∀ (i : ι), f i ≠ 0 → i ∈ s
@Nat.multinomial_spec : ∀ {α : Type u_1} (s : Finset α) (f : α → ℕ),
  (∏ i ∈ s, (f i).factorial) * Nat.multinomial s f = (∑ i ∈ s, f i).factorial
@Finset.sum_boole : ∀ {ι : Type u_1} {R : Type u_2} [inst : AddCommMonoidWithOne R] (p : ι → Prop)
  [inst_1 : DecidablePred p] (s : Finset ι), (∑ x ∈ s, if p x then 1 else 0) = ↑{x ∈ s | p x}.card

